import {sourcePoint,validRegion}from './capture-geometry.mjs';
import {client}from './api.mjs?v=ms-4';import {needAccount,SignInNeeded,result}from './community-api.mjs';
const $=id=>document.getElementById(id),video=$('cash-video'),preview=$('cash-preview');let stream=null,region=null,start=null,confidence=null;
const note=text=>$('cash-status').textContent=text;
const run=fn=>async e=>{e?.preventDefault();try{await fn();}catch(err){if(!(err instanceof SignInNeeded))note(err.message);}};
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;region=null;preview.hidden=true;$('cash-read').disabled=true;note('Cash Shop sharing stopped. Draft fields remain on this page.');}
$('cash-share').onclick=run(async()=>{if(!$('cash-consent').checked)throw Error('Agree to local region capture first.');if(!navigator.mediaDevices?.getDisplayMedia)throw Error('Use a desktop browser with screen sharing.');stop();stream=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:1},audio:false});video.srcObject=stream;await video.play();stream.getVideoTracks()[0].addEventListener('ended',stop,{once:true});preview.width=video.videoWidth;preview.height=video.videoHeight;preview.getContext('2d').drawImage(video,0,0);preview.hidden=false;note('Drag around one visible Cash Shop item card. Only this region is read when you press Read selected card.');});
$('cash-stop').onclick=stop;
const point=e=>{const b=preview.getBoundingClientRect();return sourcePoint({x:e.clientX,y:e.clientY},{x:b.left,y:b.top,width:b.width,height:b.height},{width:preview.width,height:preview.height});};
preview.onpointerdown=e=>{start=point(e);preview.setPointerCapture(e.pointerId);};
preview.onpointerup=e=>{if(!start)return;const end=point(e);region={x:Math.round(Math.min(start.x,end.x)),y:Math.round(Math.min(start.y,end.y)),w:Math.round(Math.abs(start.x-end.x)),h:Math.round(Math.abs(start.y-end.y))};start=null;if(!validRegion(region,video.videoWidth,video.videoHeight)||region.w<16||region.h<16){region=null;note('Select a larger card region.');return;}const g=preview.getContext('2d');g.drawImage(video,0,0);g.strokeStyle='#306c40';g.lineWidth=3;g.strokeRect(region.x,region.y,region.w,region.h);$('cash-read').disabled=false;note('Card region selected. Review what is visible before reading.');};
$('cash-read').onclick=run(async()=>{if(!stream||!validRegion(region,video.videoWidth,video.videoHeight))throw Error('Share a window and select one item card.');if(!window.mesosCapture?.withOCR)throw Error('OCR engine is still loading.');const crop=document.createElement('canvas');crop.width=region.w*3;crop.height=region.h*3;const g=crop.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(video,region.x,region.y,region.w,region.h,0,0,crop.width,crop.height);$('cash-read').disabled=true;try{const r=await window.mesosCapture.withOCR(async worker=>{await worker.setParameters({tessedit_pageseg_mode:'6',tessedit_char_whitelist:''});return worker.recognize(crop);});confidence=r.data.confidence;$('cash-ocr').textContent=r.data.text;note('OCR confidence '+Math.round(confidence)+'%. Enter and review the structured fields below. OCR never publishes an item automatically.');}finally{$('cash-read').disabled=false;}});
$('cash-submit').onsubmit=run(async()=>{await needAccount($('cash-submit'),'Sign in to submit Cash Shop prices.');if(!$('cash-reviewed').checked)throw Error('Review the fields and confirm they match the selected card.');const nx=$('cash-price').value;await result((await client()).from('cash_item_candidates').insert({name:$('cash-name').value.trim(),nx_price:nx===''?null:Number(nx),category:$('cash-category').value.trim(),description:$('cash-description').value.trim(),source_note:$('cash-source').value.trim(),confidence}));note('Candidate submitted for admin review. NX currency is separate from mesos; this does not publish an item or prove exhaustive coverage.');});
$('cash-consent').onchange=()=>{if(!$('cash-consent').checked)stop();};
video.addEventListener('resize',()=>{region=null;$('cash-read').disabled=true;if(stream)note('Resolution changed. Stop sharing and reconnect before selecting another card.');});
window.addEventListener('beforeunload',()=>stream?.getTracks().forEach(t=>t.stop()));
